// garden-worlds: Garden of Delight's gardens, kept online (one Durable Object per garden, SQLite-backed).
//
// Two kinds of garden:
//   s<16 letters>   your own garden. Reached by a secret link (its id and a key); the key's hash is kept, never the key.
//   r-ABCD          a room's garden, by its four-letter code. Anyone in the room can read and save it.
// A garden is a few named parts (the wall and free builds, the planting, the junk heap, the junk's pieces), each a JSON string.
// A save sends only the parts that changed; the rest carry over. Parts are stored by their SHA-256, in chunks, so a part that has not
// changed between saves is stored once. The last 12 saves are kept, so a bad save (or a vandal in a room) can be undone.
//
//   GET  /w/:id            the latest save: { rev, t, parts: { name: string } }   (?rev=n for an earlier one)
//   GET  /w/:id/meta       { rev, t, hashes: { name: sha256 }, sizes }, or 404 if never saved
//   GET  /w/:id/revs       [{ rev, t, size }], newest first
//   PUT  /w/:id            { parts: { name: string } } -> { rev, t }
//   GET  /room/new         a four-letter room code no saved garden has yet
// Your own garden wants the key in an x-key header. Saves are refused more often than every 4 s, or bigger than 24 MB in all.

const CORS = { 'access-control-allow-origin': '*', 'access-control-allow-methods': 'GET, PUT, OPTIONS', 'access-control-allow-headers': 'content-type, x-key', 'access-control-max-age': '86400' };
const json = (o, status = 200) => new Response(JSON.stringify(o), { status, headers: { 'content-type': 'application/json', 'cache-control': 'no-store', ...CORS } });
const ID = /^(s[a-z2-7]{16}|r-[BCDFGHJKLMNPQRSTVWXZ]{4})$/, PART = /^[a-z]{2,12}$/;
const KEEP = 12, CHUNK = 1 << 20, MAX_TOTAL = 24 << 20, MIN_GAP = 4000;
const hex = buf => [...new Uint8Array(buf)].map(b => b.toString(16).padStart(2, '0')).join('');
const sha = async s => hex(await crypto.subtle.digest('SHA-256', new TextEncoder().encode(s)));
const LETTERS = 'BCDFGHJKLMNPQRSTVWXZ';

export class World {
  constructor(ctx, env) {
    this.ctx = ctx; this.sql = ctx.storage.sql;
    this.sql.exec(`CREATE TABLE IF NOT EXISTS meta (k TEXT PRIMARY KEY, v TEXT);
      CREATE TABLE IF NOT EXISTS blob (h TEXT, i INTEGER, d TEXT, PRIMARY KEY (h, i));
      CREATE TABLE IF NOT EXISTS rev (n INTEGER PRIMARY KEY, t INTEGER, parts TEXT, size INTEGER)`);
  }
  meta(k) { const r = this.sql.exec('SELECT v FROM meta WHERE k = ?', k).toArray()[0]; return r ? r.v : null; }
  setMeta(k, v) { this.sql.exec('INSERT INTO meta (k, v) VALUES (?, ?) ON CONFLICT(k) DO UPDATE SET v = excluded.v', k, String(v)); }
  latest() { return this.sql.exec('SELECT n, t, parts, size FROM rev ORDER BY n DESC LIMIT 1').toArray()[0] || null; }
  read(h) { return this.sql.exec('SELECT d FROM blob WHERE h = ? ORDER BY i', h).toArray().map(r => r.d).join(''); }
  async fetch(req) {
    const url = new URL(req.url), [, , id, what] = url.pathname.split('/');
    // your own garden: the key it was first saved with
    if (id[0] === 's') {
      const kh = this.meta('key'), given = req.headers.get('x-key') || '';
      if (given.length < 16 || given.length > 64) return json({ error: 'key' }, 403);
      const h = await sha('gd-key:' + given);
      if (kh && kh !== h) return json({ error: 'key' }, 403);
      if (!kh && req.method === 'PUT') this.setMeta('key', h);
    }
    if (req.method === 'GET') {
      if (what === 'revs') return json(this.sql.exec('SELECT n AS rev, t, size FROM rev ORDER BY n DESC').toArray());
      const n = url.searchParams.get('rev'), r = n ? this.sql.exec('SELECT n, t, parts, size FROM rev WHERE n = ?', +n).toArray()[0] : this.latest();
      if (!r) return json({ error: 'none' }, 404);
      const P = JSON.parse(r.parts);
      if (what === 'meta') return json({ rev: r.n, t: r.t, hashes: Object.fromEntries(Object.entries(P).map(([k, v]) => [k, v[0]])), sizes: Object.fromEntries(Object.entries(P).map(([k, v]) => [k, v[1]])) });
      const parts = {}; for (const [k, [h]] of Object.entries(P)) parts[k] = this.read(h);
      return json({ rev: r.n, t: r.t, parts });
    }
    if (req.method === 'PUT') {
      const now = Date.now(), last = +(this.meta('put') || 0);
      if (now - last < MIN_GAP) return json({ error: 'too soon', wait: MIN_GAP - (now - last) }, 429);
      let body; try { body = await req.json(); } catch (e) { return json({ error: 'not json' }, 400); }
      const given = body && body.parts && typeof body.parts === 'object' ? body.parts : null; if (!given) return json({ error: 'no parts' }, 400);
      const prev = this.latest(), P = prev ? JSON.parse(prev.parts) : {};
      for (const [k, s] of Object.entries(given)) {
        if (!PART.test(k) || Object.keys(P).length > 12) return json({ error: 'part ' + k }, 400);
        if (s === null) { delete P[k]; continue; }
        if (typeof s !== 'string') return json({ error: 'part ' + k }, 400);
        const h = await sha(s);
        if (!this.sql.exec('SELECT 1 FROM blob WHERE h = ? LIMIT 1', h).toArray().length)
          for (let i = 0, j = 0; i < s.length || j === 0; i += CHUNK, j++) this.sql.exec('INSERT INTO blob (h, i, d) VALUES (?, ?, ?)', h, j, s.slice(i, i + CHUNK));
        P[k] = [h, s.length];
      }
      const size = Object.values(P).reduce((a, v) => a + v[1], 0);
      if (size > MAX_TOTAL) return json({ error: 'too big', size }, 413);
      const n = (prev ? prev.n : 0) + 1;
      this.sql.exec('INSERT INTO rev (n, t, parts, size) VALUES (?, ?, ?, ?)', n, now, JSON.stringify(P), size);
      this.setMeta('put', now);
      // keep the last few saves; let go of any part none of them uses
      this.sql.exec('DELETE FROM rev WHERE n <= ?', n - KEEP);
      const used = new Set(); for (const r of this.sql.exec('SELECT parts FROM rev').toArray()) for (const v of Object.values(JSON.parse(r.parts))) used.add(v[0]);
      for (const r of this.sql.exec('SELECT DISTINCT h FROM blob').toArray()) if (!used.has(r.h)) this.sql.exec('DELETE FROM blob WHERE h = ?', r.h);
      return json({ rev: n, t: now });
    }
    return json({ error: 'method' }, 405);
  }
}

export default {
  async fetch(req, env) {
    if (req.method === 'OPTIONS') return new Response(null, { status: 204, headers: CORS });
    const url = new URL(req.url), seg = url.pathname.split('/');
    if (seg[1] === 'room' && seg[2] === 'new' && req.method === 'GET') {
      for (let k = 0; k < 6; k++) {
        let c = ''; for (let i = 0; i < 4; i++) c += LETTERS[Math.floor(Math.random() * LETTERS.length)];
        const r = await env.WORLD.get(env.WORLD.idFromName('r-' + c)).fetch(new Request(`https://w/w/r-${c}/meta`));
        if (r.status === 404) return json({ code: c });
      }
      return json({ error: 'busy' }, 503);
    }
    if (seg[1] !== 'w' || !ID.test(seg[2] || '') || seg.length > 4 || (seg[3] && !['meta', 'revs'].includes(seg[3]))) return json({ error: 'not found' }, 404);
    if (req.method === 'PUT' && +(req.headers.get('content-length') || 0) > MAX_TOTAL + (1 << 20)) return json({ error: 'too big' }, 413);
    return env.WORLD.get(env.WORLD.idFromName(seg[2])).fetch(req);
  },
};
